import{_ as t,l as s,o as a,c,v as r,p as i,x as o,d as n,i as l,S as p}from"./chunks/framework.InCnrqk-.js";const R=JSON.parse('{"title":"寄存器堆","description":"","frontmatter":{"title":"寄存器堆","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/register-file.md","filePath":"cs/register-file.md","lastUpdated":1789023840000}'),h={name:"cs/register-file.md"};function _(f,e,m,u,E,A){const d=s("Mermaid");return a(),c("div",null,[e[1]||(e[1]=r('<h1 id="寄存器堆" tabindex="-1">寄存器堆 <a class="header-anchor" href="#寄存器堆" aria-label="Permalink to &quot;寄存器堆&quot;">​</a></h1><div class="epigraph"><p>ISA 的 `rs1`、`rs2`、`rd` 是端口上的地址；堆是多口 SRAM，读组合、写在时钟边沿。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V)；Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p>上一课<a href="/cs/pseudo-instructions">伪指令</a>钉死了多数指令要读两个寄存器、写一个。本课不重列 <code>add</code> 语义，也不从编译器着色另起。缺口是：<strong>32 个 <code>x</code> 寄存器</strong>如何做成电路——不是 32 个分散的命名寄存器手工接线，而是带译码的寄存器堆。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/cs/register-shift">寄存器</a>课只有一个字。<a href="/cs/memory-array-sram-dram">阵列</a>课有单口大容量。缺口是小而多口：两个组合读口（地址 <code>rs1</code>/<code>rs2</code>，数据 <code>R1</code>/<code>R2</code>），一个同步写口（<code>rd</code>、<code>RegWrite</code>、<code>WriteData</code>）。<code>x0</code> 读恒 0、写忽略。内部：32×32 SRAM 或 FF 阵列加两个读 MUX/译码。</p><p>写后读（同一条指令内）在单周期里通常「本拍写的下拍才可见」，RISC-V 不要求同一指令读自己的 <code>rd</code>。旁路是流水线课。</p><h3 id="寄存器堆不是「主存的前-32-个字」" tabindex="-1">寄存器堆不是「主存的前 32 个字」 <a class="header-anchor" href="#寄存器堆不是「主存的前-32-个字」" aria-label="Permalink to &quot;寄存器堆不是「主存的前 32 个字」&quot;">​</a></h3><p>地址空间里的内存与 <code>x</code> 寄存器是不同结构。<code>lw</code> 把内存搬进寄存器，不是给内存取别名。把 <code>x10</code> 当成地址 <code>10</code> 的 DRAM 单元，调用约定与指针会全部塌掉。</p><p><span class="marginnote">Patterson/Hennessy 把 register file 画成双读单写框。Harris 给出寄存器堆的实现草图。写口用<a href="/cs/decoder-encoder">译码器</a>产生 32 根使能。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读：地址译码选行，组合读出，延迟计入 \\(t_{pd}\\)。写：边沿、使能、<code>rd≠0</code>。两口同时读同一寄存器应得到同一值。读口与写口同一地址时的旁路策略在单周期可定义为「读旧值」。</p>',11)),(a(),i(p,null,{default:o(()=>[l(d,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20RS%5B%22rs1%2C%20rs2%22%5D%20--%3E%20RF%5B%2232%C3%9732%20%E5%8F%8C%E8%AF%BB%E5%8D%95%E5%86%99%22%5D%0A%20%20RD%5B%22rd%20%2B%20RegWrite%22%5D%20--%3E%20RF%0A%20%20RF%20--%3E%20OP%5B%22%E5%88%B0%20ALU%20%2F%20%E5%9F%BA%E5%9D%80%22%5D%0A%20%20RF%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%8D%95%E5%91%A8%E6%9C%9F%E6%95%B4%E5%9B%BE%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>调用约定把参数放进 <code>x10</code>–<code>x17</code> 等，是软件对这 32 个槽的用法，硬件一视同仁——<a href="/cs/calling-convention-stack">调用约定</a>再钉。PC 通常不在整数堆里，是单独寄存器。CSR 是另一组，特权课才碰。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲物理寄存器重命名、不把浮点 <code>f</code> 堆画进来。不讨论多核各有一份堆。扫描链、调试口是实现附件。</p><p>后课默认：RV32I 的整数状态在双读单写寄存器堆；<code>x0</code> 硬 0。单周期数据通路把堆与 ALU、内存、PC 接在一起。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>寄存器堆实现 ISA 的 32 个整数寄存器，双读单写。</li><li>读组合、写同步；<code>x0</code> 特殊。</li><li>与主存分离；<code>lw</code>/<code>sw</code> 在二者之间搬数据。</li><li>出处：Patterson and Hennessy, COD (RISC-V)；Harris and Harris。</li></ul>',7))])}const g=t(h,[["render",_]]);export{R as __pageData,g as default};
